contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount > 0);
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.donate{value: amount}(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.ethBalance(); if (__ESBMC_reverted()) return;
        uint256 potFirst = c.winnersPot(); if (__ESBMC_reverted()) return;
        uint256 potSecond = c.winnersPot(); if (__ESBMC_reverted()) return;
        assert(potFirst == balBefore / 2 && potSecond == balBefore / 2);
    }

    receive() external payable {}
}

