    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount > 0);
        try c.OpenToThePublic() {} catch { return; }
        try c.donate{value: amount}() {} catch { return; }
        uint256 balBefore;
        try c.ethBalance() returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 potFirst;
        try c.winnersPot() returns (uint256 __r) { potFirst = __r; } catch { return; }
        uint256 potSecond;
        try c.winnersPot() returns (uint256 __r) { potSecond = __r; } catch { return; }
        assertTrue(potFirst == balBefore / 2 && potSecond == balBefore / 2);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
